import {supabase,currentUser} from './auth-client.mjs';import {albumShareText} from './album-model.mjs';
const $=id=>document.getElementById(id),root=new URL('./album-data/',import.meta.url),el=(t,s,c)=>{const n=document.createElement(t);if(s!==undefined)n.textContent=s;if(c)n.className=c;return n;};
let data,user,profile={},ready=false,gold=false,revision=0,selectedSet=1,tradeMode='Same Rarity',tradesLeft=3;const inventory=new Map(),priorities=new Map(),pending=new Set();
function message(s){$('album-status').textContent=s;}
function render(){let total=0,golds=0;for(const c of data.cards)if((inventory.get(c.number)?.quantity||0)>0){total++;if(c.gold)golds++;}$('album-progress').textContent=ready?total+' / 135':'— / 135';$('gold-progress').textContent=ready?golds+' / 17':'— / 17';$('trade-mode-inline').value=tradeMode;
 $('album-set-strip').replaceChildren(...data.sets.map(set=>{const b=el('button',undefined,'set-choice');b.type='button';b.setAttribute('aria-label',set.name);b.setAttribute('aria-pressed',String(set.number===selectedSet));const picture=el('img');picture.src=new URL(set.image,root);picture.alt=set.name;const count=ready?set.cards.filter(n=>(inventory.get(n)?.quantity||0)>0).length:0;b.append(picture,el('span',set.name),el('small',String(count),'set-count'));b.onclick=()=>{selectedSet=set.number;render();};return b;}));
 const query=$('card-search').value.trim().toLowerCase(),cards=data.cards.filter(c=>(query||c.set===selectedSet)&&(!query||String(c.number).includes(query)||c.name.toLowerCase().includes(query)));$('album-sets').replaceChildren(...cards.map(card=>{const record=inventory.get(card.number),q=record?.quantity||0,tile=el('article',undefined,'album-card'+(q?' collected':''));tile.dataset.card=card.number;const frame=el('div',undefined,'card-picture'),art=el('img');art.className='card-art';art.src=new URL(card.image,root);art.alt=card.name;art.loading='lazy';const owned=el('strong',ready&&q?'Owned: '+q:'','owned-overlay');const stars=el('img');stars.src=new URL('../tatari-data/stars/'+String(card.stars).padStart(2,'0')+'.png',root);stars.alt=card.stars+' stars';stars.className='album-card-stars';frame.append(art,owned,stars);const controls=el('div',undefined,'quantity-controls');for(const delta of [-1,1]){const b=el('button',undefined,'quantity-button'),symbol=el('img');b.type='button';b.setAttribute('aria-label',(delta>0?'Add':'Remove')+' card '+card.number);symbol.src=new URL('ui/'+(delta>0?'plus':'minus')+'.png',root);symbol.alt='';b.append(symbol);b.disabled=!ready||pending.has(card.number)||(delta<0?q===0:q>=999);b.onclick=()=>adjust(card,delta);controls.append(b);}tile.append(frame,controls,el('h3','#'+card.number+(card.gold?'G':'')+' · '+card.name));if(record?.updated_at)tile.title='Updated '+new Date(record.updated_at).toLocaleString();return tile;}));if(!cards.length)$('album-sets').append(el('p','No matching cards.'));}
async function adjust(card,delta){if(!ready||pending.has(card.number))return;const token=revision;pending.add(card.number);document.querySelector('[data-card="'+card.number+'"]')?.querySelectorAll('button').forEach(b=>b.disabled=true);try{const {data:rows,error}=await supabase.rpc('album_adjust_quantity',{p_season:data.season,p_card:card.number,p_delta:delta});if(error)throw error;if(token!==revision)return;if(!rows?.length)throw Error('Save could not be confirmed.');inventory.set(card.number,rows[0]);message('');}catch(e){message(e.message);}finally{pending.delete(card.number);render();}}
async function load(){if(!data)return;const token=++revision;ready=false;inventory.clear();priorities.clear();profile={};$('share-album').disabled=true;$('save-trade-preferences').disabled=true;$('trade-mode-inline').disabled=true;try{user=await currentUser();if(!user){message('Log in to manage your album.');render();return;}const [cards,prefs,priority,contact,status]=await Promise.all([supabase.from('card_inventory').select('card_number,quantity,updated_at').eq('user_id',user.id).eq('season_id',data.season),supabase.from('album_trade_preferences').select('*').eq('user_id',user.id).eq('season_id',data.season).maybeSingle(),supabase.from('album_priorities').select('set_number,priority').eq('user_id',user.id).eq('season_id',data.season),supabase.from('profiles').select('game_id,discord_username').eq('user_id',user.id).maybeSingle(),supabase.rpc('album_exchange_status',{p_season:data.season})]);if(token!==revision)return;for(const r of [cards,prefs,priority,contact])if(r.error)throw r.error;for(const c of cards.data)inventory.set(c.card_number,c);for(const p of priority.data)priorities.set(p.set_number,p.priority);profile=contact.data||{};tradeMode=prefs.data?.rarity_mode||(prefs.data?.accept_any?'Any Rarity':prefs.data?.accept_up||prefs.data?.accept_down?'Flexible Rarity':'Same Rarity');tradesLeft=prefs.data?.trades_left_today??3;$('trades-left').value=tradesLeft;gold=!status.error&&status.data===true;$('gold-status').textContent=gold?'Gold Exchange active':'Gold Exchange locked';ready=true;$('share-album').disabled=false;$('save-trade-preferences').disabled=false;$('trade-mode-inline').disabled=false;message('');render();}catch(e){message('Album settings are unavailable: '+e.message);render();}}
async function savePrefs(){if(!ready)return;const row={user_id:user.id,season_id:data.season,rarity_mode:tradeMode,trades_left_today:tradesLeft,accept_equal:tradeMode!=='Any Rarity',accept_up:tradeMode==='Flexible Rarity',accept_down:tradeMode==='Flexible Rarity',accept_any:tradeMode==='Any Rarity'};const {error}=await supabase.from('album_trade_preferences').upsert(row,{onConflict:'user_id,season_id'});if(error)throw error;}
$('trade-settings').onclick=()=>{$('rarity-mode').value=tradeMode;$('set-priority').value=priorities.get(selectedSet)||2;$('trade-dialog').showModal();};$('close-trade').onclick=()=>$('trade-dialog').close();
$('save-trade-preferences').onclick=async()=>{const previous=tradeMode;tradeMode=$('rarity-mode').value;$('save-trade-preferences').disabled=true;try{await savePrefs();const p=Number($('set-priority').value),{error}=await supabase.from('album_priorities').upsert({user_id:user.id,season_id:data.season,set_number:selectedSet,priority:p},{onConflict:'user_id,season_id,set_number'});if(error)throw error;priorities.set(selectedSet,p);$('trade-dialog').close();render();}catch(e){tradeMode=previous;$('trade-status').textContent=e.message;}finally{$('save-trade-preferences').disabled=!ready;}};
$('trades-left').onchange=async()=>{const n=Number($('trades-left').value);if(!Number.isInteger(n)||n<0||n>3){$('trades-left').value=tradesLeft;message('Trades left must be 0–3.');return;}const old=tradesLeft;tradesLeft=n;try{await savePrefs();message('');}catch(e){tradesLeft=old;$('trades-left').value=old;message(e.message);}};
$('share-album').title='Copy your card lists, saved Discord username and in-game ID';$('share-album').onclick=async()=>{if(!ready)return;try{await navigator.clipboard.writeText(albumShareText(data,inventory,profile,tradeMode,tradesLeft,gold));message('Copied to clipboard.');}catch(e){message('Could not copy: '+e.message);}};
$('card-search').oninput=render;supabase.auth.onAuthStateChange(()=>setTimeout(load,0));try{const r=await fetch(new URL('autumn-tales.json?v=compact',root));if(!r.ok)throw Error('Album data unavailable.');data=await r.json();render();await load();}catch(e){message(e.message);}
setInterval(async()=>{if(!data)return;const {data:active,error}=await supabase.rpc('album_exchange_status',{p_season:data.season});gold=!error&&active===true;$('gold-status').textContent=gold?'Gold Exchange active':'Gold Exchange locked';},60000);


$('trade-mode-inline').onchange=async()=>{if(!ready)return;const before=tradeMode;tradeMode=$('trade-mode-inline').value;$('trade-mode-inline').disabled=true;try{await savePrefs();message('');}catch(error){tradeMode=before;message(error.message);}finally{$('trade-mode-inline').disabled=!ready;render();}};

window.addEventListener('game-uid-saved',load);
